339:     @Override
340:     public void publishProject(long id, String description, boolean syncWithGit) {
341:         Project project = projectService.getProject(id);
342: 
343:         int oldProjectVersion = project.getLastVersion();
344: 
345:         List<ProjectWorkflow> oldProjectWorkflows = projectWorkflowService.getProjectWorkflows(
346:             project.getId(), oldProjectVersion);
347: 
348:         int newProjectVersion = projectService.publishProject(id, description, syncWithGit);
349: 
350:         for (ProjectWorkflow oldProjectWorkflow : oldProjectWorkflows) {
351:             String oldWorkflowId = oldProjectWorkflow.getWorkflowId();
352: 
353:             Workflow duplicatedWorkflow = workflowService.duplicateWorkflow(oldWorkflowId);
354: 
355:             oldProjectWorkflow.setProjectVersion(newProjectVersion);
356:             oldProjectWorkflow.setWorkflowId(duplicatedWorkflow.getId());
357: 
358:             projectWorkflowService.update(oldProjectWorkflow);
359: 
360:             projectWorkflowService.addWorkflow(
361:                 project.getId(), oldProjectVersion, oldWorkflowId, oldProjectWorkflow.getWorkflowReferenceCode());
362: 
363:             workflowTestConfigurationService.updateWorkflowId(oldWorkflowId, duplicatedWorkflow.getId());
364:             workflowNodeTestOutputService.updateWorkflowId(oldWorkflowId, duplicatedWorkflow.getId());
365:         }
366:     }
