406:     private List<String> copyWorkflowIds(List<String> workflowIds) {
407:         List<String> newWorkflowIds = new ArrayList<>();
408: 
409:         for (String workflowId : workflowIds) {
410:             Workflow workflow = workflowService.getWorkflow(workflowId);
411: 
412:             workflow = workflowService.create(
413:                 workflow.getDefinition(), workflow.getFormat(), workflow.getSourceType());
414: 
415:             newWorkflowIds.add(workflow.getId());
416:         }
417:         return newWorkflowIds;
418:     }
