420:     private String generateName(String oldName) {
421:         List<Project> projects = projectService.getProjects();
422: 
423:         int addendum = 0;
424: 
425:         for (Project curProject : projects) {
426:             String name = curProject.getName();
427: 
428:             if (name.startsWith(oldName)) {
429:                 addendum++;
430:             }
431:         }
432: 
433:         return oldName + " (%s)".formatted(addendum);
434:     }
