440:     private List<ProjectDTO> getProjects(
441:         Long workspaceId, boolean projectDeployments, Long categoryId, Long tagId, Status status, List<Long> projectIds,
442:         boolean includeAllFields) {
443: 
444:         projectIds = new ArrayList<>(projectIds);
445: 
446:         if (projectDeployments) {
447:             projectIds.addAll(projectDeploymentService.getProjectDeploymentProjectIds());
448:         }
449: 
450:         List<Project> projects = projectService.getProjects(workspaceId, projectIds, categoryId, tagId, status);
451: 
452:         if (includeAllFields) {
453:             return CollectionUtils.map(
454:                 projects,
455:                 project -> new ProjectDTO(
456:                     CollectionUtils.findFirstFilterOrElse(
457:                         categoryService.getCategories(
458:                             projects
459:                                 .stream()
460:                                 .map(Project::getCategoryId)
461:                                 .filter(Objects::nonNull)
462:                                 .toList()),
463:                         category -> Objects.equals(project.getCategoryId(), category.getId()),
464:                         null),
465:                     project,
466:                     projectWorkflowService.getProjectWorkflowIds(project.getId(), project.getLastVersion()),
467:                     CollectionUtils.filter(
468:                         tagService.getTags(
469:                             projects.stream()
470:                                 .flatMap(curProject -> CollectionUtils.stream(curProject.getTagIds()))
471:                                 .filter(Objects::nonNull)
472:                                 .toList()),
473:                         tag -> CollectionUtils.contains(project.getTagIds(), tag.getId()))));
474:         } else {
475:             return CollectionUtils.map(projects, ProjectDTO::new);
476:         }
477:     }
478: 
479:     private ProjectDTO toProjectDTO(Project project) {
480:         return new ProjectDTO(
481:             getCategory(project), project,
482:             projectWorkflowService.getProjectWorkflowIds(project.getId(), project.getLastVersion()),
483:             tagService.getTags(project.getTagIds()));
484:     }
485: }
