+                                    <LeftSidebarNavItem
+                                        item={{
+                                            current: environment === item.value,
+                                            id: item.value,
+                                            name: item.label,
+                                        }}
+                                        key={item.value ?? ''}
+                                        toLink={`?environment=${item.value ?? ''}`}
+                                    />
+                                ))}
+                            </>
+                        }
