106:         List<String> exclude = registry.getExclude();
107: 
108:         if (!CollectionUtils.isEmpty(exclude)) {
109:             componentDefinitions = componentDefinitions.stream()
110:                 .filter(componentDefinition -> !CollectionUtils.contains(exclude, componentDefinition.getName()))
111:                 .toList();
112:         }
113: 
114:         // Validate
115: 
116:         validate(componentDefinitions);
117: 
118:         for (ComponentDefinition componentDefinition : componentDefinitions) {
119:             this.componentDefinitionsMap
120:                 .computeIfAbsent(StringUtils.upperCase(componentDefinition.getName()), key -> new HashMap<>())
121:                 .put(componentDefinition.getVersion(), componentDefinition);
122:         }
123: 
124:         this.dynamicComponentHandlerListFactories = dynamicComponentHandlerRegistries;
125:     }
