127:     public Optional<ComponentDefinition> fetchComponentDefinition(String name, @Nullable Integer version) {
128:         ComponentDefinition componentDefinition = null;
129: 
130:         if (version == null) {
131:             List<ComponentDefinition> filteredComponentDefinitions = getComponentDefinitions(name);
132: 
133:             if (!filteredComponentDefinitions.isEmpty()) {
134:                 componentDefinition = filteredComponentDefinitions.getLast();
135:             }
136:         } else {
137:             Map<Integer, ComponentDefinition> componentDefinitionMap = componentDefinitionsMap.get(
138:                 StringUtils.upperCase(name));
139: 
140:             if (componentDefinitionMap != null) {
141:                 componentDefinition = componentDefinitionMap.get(version);
142: 
143:                 if (componentDefinition == null) {
144:                     componentDefinition = dynamicComponentHandlerListFactories.stream()
145:                         .map(
146:                             dynamicComponentHandlerRegistry -> dynamicComponentHandlerRegistry.fetchComponentHandler(
147:                                 name, version))
148:                         .filter(Optional::isPresent)
149:                         .map(Optional::get)
150:                         .findFirst()
151:                         .map(ComponentHandler::getDefinition)
152:                         .orElse(null);
153:                 }
154:             }
155:         }
156: 
157:         return Optional.ofNullable(componentDefinition);
158:     }
