166:                     .toList(),
167:                 dynamicComponentHandlerListFactories.stream()
168:                     .flatMap(dynamicComponentHandlerRegistry -> CollectionUtils.stream(
169:                         dynamicComponentHandlerRegistry.getComponentHandlers()))
170:                     .map(ComponentHandler::getDefinition)
