69: 
70:         PrivateKey privateKey = getPrivateRSAKeyFromString(inputParameters.getRequiredString(PRIVATE_KEY));
71: 
72:         Cipher cipher = Cipher.getInstance("RSA/ECB/PKCS1Padding");
73:         cipher.init(Cipher.DECRYPT_MODE, privateKey);
74: 
75:         int maxBlockSize = 256;
76:         ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
77: 
78:         int offset = 0;
79:         while (offset < encryptedData.length) {
80:             int chunkSize = Math.min(maxBlockSize, encryptedData.length - offset);
81:             byte[] chunck = cipher.doFinal(encryptedData, offset, chunkSize);
82:             byteArrayOutputStream.write(chunck);
83:             offset += chunkSize;
84:         }
85: 
86:         return context.file(
87:             file -> file.storeContent("decrypted.",
88:                 new ByteArrayInputStream(byteArrayOutputStream.toByteArray())));
89:     }
